 58	// ---------------------------------------------------------------------------
 59	// Public API
 60	// ---------------------------------------------------------------------------
 61	
 62	/**
 63	 * Wires all server components together, starts listening, and kicks off the
 64	 * background polling loop.
 65	 *
 66	 * The returned promise resolves once the server is actually listening on the
 67	 * chosen port (i.e. after the `listening` event fires).
 68	 *
 69	 * If the port is already in use (`EADDRINUSE`), the promise rejects with a
 70	 * descriptive `Error` and an actionable log message is printed to stderr.
 71	 *
 72	 * Calling `startServer()` while a server is already running throws
 73	 * synchronously.
 74	 *
 75	 * Internally creates an `ErrorLogManager` shared across all subsystems
 76	 * (WorkspaceOrchestrator, BranchOrchestrator, PollingManager, and Router);
 77	 * no external reference is returned.
 78	 */
 79	export function startServer(config: ServerConfig): Promise<void> {
 80	    if (_server !== null) {
 81	        throw new Error('Server is already running. Call stopServer() first.');
 82	    }
 83	
 84	    const port = config.serverPort ?? config.appConfig.serverPort ?? 4200;
 85	    const pollInterval = config.pollIntervalSeconds ?? config.appConfig.gitPollingIntervalSeconds ?? 30;
 86	
 87	    // ------------------------------------------------------------------
 88	    // Instantiate managers & orchestrators
 89	    // ------------------------------------------------------------------
 90	    const repoManager = new RepositoryManager(config.appConfig);
 91	    const projectManager = new ProjectManager(config.appConfig, repoManager);
 92	    const workspaceManager = new WorkspaceManager(projectManager);
 93	    const errorLogManager = new ErrorLogManager(config.appConfig);
 94	    const workspaceOrchestrator = new WorkspaceOrchestrator(
 95	        config.appConfig,
 96	        projectManager,
 97	        workspaceManager,
 98	        repoManager,
 99	        errorLogManager,
100	    );

101	    const branchOrchestrator = new BranchOrchestrator(
102	        config.appConfig,
103	        projectManager,
104	        workspaceManager,
105	        errorLogManager,
106	    );
107	    const pollingManager = new PollingManager(
108	        config.appConfig,
109	        projectManager,
110	        workspaceManager,
111	        undefined,       // fetchStatusFn — use the default real git layer
112	        errorLogManager,
113	    );
114	
115	    // ------------------------------------------------------------------
116	    // Build the router and register all route groups
117	    // ------------------------------------------------------------------
118	    const router = new Router();
119	    router.setErrorLogManager(errorLogManager);
120	    registerRepositoryRoutes(router, repoManager);
121	    registerProjectRoutes(router, projectManager);
122	    registerWorkspaceRoutes(router, workspaceManager, workspaceOrchestrator, config.appConfig);
123	    registerBranchRoutes(router, branchOrchestrator, workspaceManager);
124	    registerStatusRoutes(router, pollingManager, projectManager, workspaceManager, config.appConfig);
125	    registerConfigRoutes(router, config.appConfig, undefined, pollingManager);
126	    registerErrorLogRoutes(router, errorLogManager);
127	
128	    // ------------------------------------------------------------------
129	    // Create HTTP server with the static-first request pipeline
130	    // ------------------------------------------------------------------
131	    const server = http.createServer((req: IncomingMessage, res: ServerResponse) => {
132	        // Static files are checked first; if the file exists it is served and
133	        // we return immediately without consulting the router.
134	        serveStatic(req, res, config.staticDir)
135	            .then((served) => {
136	                if (!served) {
137	                    // Not a static file — hand off to the API router.
138	                    // The router writes its own 404 when nothing matches.
139	                    router.handle(req, res);
140	                }
141	            })
142	            .catch(() => {
143	                // Should not happen (serveStatic only rejects on programmer
144	                // error), but guard anyway to avoid unhandled-rejection noise.
145	                sendError(res, 500, 'Internal server error.');
146	            });
147	    });
148	
149	    // ------------------------------------------------------------------
150	    // Return a promise that resolves on 'listening' and rejects on error
151	    // ------------------------------------------------------------------
152	    return new Promise<void>((resolve, reject) => {
153	        server.once('error', (err: NodeJS.ErrnoException) => {
154	            if (err.code === 'EADDRINUSE') {
155	                process.stderr.write(
156	                    `[repo-parallelizer] ERROR: Port ${port} is already in use.\n` +
157	                    `  Try a different port by setting "serverPort" in your config.json.\n`,
158	                );
159	            }
160	            reject(err);
161	        });
162	
163	        server.listen(port, '127.0.0.1', () => {
164	            // Store module-level references so stopServer() can reach them.
165	            _server = server;
166	            _pollingManager = pollingManager;
167	
168	            // Kick off the background git polling loop.
169	            pollingManager.start(pollInterval);
170	
171	            resolve();
172	        });
173	    });
174	}
